//   uPaperRgb             vec3       linear albedo
//   uPaperBrdf            vec4       Oren–Nayar σ [rad]; sheen; sheen α; translucency
//   uPaperPat             vec4       stock (0 cotton, 1 felt, 2 smooth, 3 laid, 4 linen, 5 kraft); formation contrast;
